"""Summarize current build checks without copying historical gameplay claims."""
from pathlib import Path
import argparse,hashlib,json,re,tomllib
root=Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser()
parser.add_argument('--dll',type=Path,default=root/'target/release/NRHex.dll')
parser.add_argument('--dll-only',action='store_true')
parser.add_argument('--no-install',action='store_true')
args=parser.parse_args()
version=tomllib.loads((root/'Cargo.toml').read_text())['package']['version']
def hashfile(p):return hashlib.sha256(p.read_bytes()).hexdigest()
if args.dll_only:
    installed=root/'dist/mod/natives/NRHex.dll'
    report=dict(version=version,mode='dll-only',buildPassed=True,dllPath=str(args.dll),dllSha256=hashfile(args.dll),installed=not args.no_install,installedDllSha256=hashfile(installed) if installed.exists() else None,resourcesRebuilt=False,gameplayVerified=False,multiplayerVerified=False,loadingVerified=False)
    if not args.no_install:assert report['dllSha256']==report['installedDllSha256'],'Installed DLL differs from the compiled DLL'
    output=root/'work/build/dll-validation.json';output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(json.dumps(report,indent=2),encoding='utf8')
    print('PASS: DLL-only build recorded; existing resource validation reports preserved.')
    raise SystemExit(0)
reports=sorted(p.name for p in (root/'dist').glob('*validation.json') if p.name not in ['runtime-validation.json','build-validation.json','integration-validation.json','icon-validation.json','multiplayer-fixes-validation.json','sword-rework-validation.json','scope-validation.json'] and not p.name[0].isdigit())
signature_count=int(re.search(r"fn signatures\(\)->\[\(&'static str,u32\);(\d+)\]",(root/'src/lib.rs').read_text(encoding='utf8')).group(1))
report=dict(version=version,buildPassed=True,mode='full',installed=not args.no_install,signatureCount=signature_count,functionChecks=reports,dllSha256=hashfile(args.dll),installedDllSha256=hashfile(root/'dist/mod/natives/NRHex.dll'),gameplayVerified=False,multiplayerVerified=False,notes='Build/static/isolated checks only. Current user gameplay feedback is summarized in docs/implementation.md.')
(root/'dist/build-validation.json').write_text(json.dumps(report,indent=2),encoding='utf8')
runtime=dict(version=version,active=None,pid=None,allFourNativeDllsLoaded=False,build='build-validation.json',dllSha256=report['installedDllSha256'],gameplayVerified=False,multiplayerVerified=False,pendingChecks=['Draw Your Sword fixed-launch 5m independent projectile retirement, inherited child origins, native bound/area ranges, charged-hit wards, FP restoration, large targets and peers','Ominous Pact/Sword hidden synergy: owned-Sword role exception; accepted spell hits use native weapon eligibility without a caster-distance gate; shared ten-second cooldown across weapon and spell hits; peers','Mighty and Draw Your Sword hidden synergy: owned-Sword role exception, native per-contact spell/arrow/bolt/skill-projectile impact, multihit/replay, large targets and peers','Red Envelope team-native per-member outdoor reward, owner acquisition-level tier, host broadcast/guest request, one submission per owner, independent pickup, peer queue isolation and reset','Essence Reaver original on-kill attribution, one aggregate multiplicative FP effect, no standalone Buff-bar icon, preserved ability icons, death/reload restoration, compact saves, new-run reset and peer HUD','Humans are Cats inward-wall jump forward impulse on inclined walls, ordinary walls, neutral/away input and multiplayer positions','Per-option native Leave-key reroll: keyboard/controller prompt, each slot once, reopen/revival/reload, actual granted item, unchanged weapon Leave and independent peers','Per-expedition exposure cycles: all displayed choices excluded, tail-first rollover, local saved history through revival/reload, independent peers and new-run reset','Night blessing rain-only 20-percent attack, low-HP 15-second regeneration, unlimited backlash until exit and grace rearming','Ominous Pact original weapon on-hit eligibility with sorcery/incantations excluded unless Draw Your Sword converts the accepted spell hit to native weapon on-hit selection, shared ten-second game-time cooldown for multihit/multitarget attacks, native self-damage and original on-damage effects','Heartstealer charged-hit native charm mist, 30-second shared cooldown, no branch awards/returns, revival and native host/guest projectile behavior','Draw Your Sword fixed-origin radial range against large bosses; damage and regain after caster movement; Ctrl+F9 paired test ball','Keep Chanting held spell charge, cancellation, both hands and 30 stamina per game-time second','Balloon death/near-death shockwave, max-HP damage, impact 7 and revival rearming','Enhanced Necromancy wall-aware placement, capture/summon cues, 1/60 max-HP native drain, 25% damage, native family damage classification and multiplayer views','Monster Cage keyless interaction, diverse bosses, repeat spawning/rewards, no grace and native relic reward','Monster Cage draw-time native terrain exclusion in Great Hollow after death/revival, host/guest and multiplayer shared encounter arbitration','Noisy Ghost multiplayer lava phases and stack damage','Weapon drop/pickup overlay restoration','Cross-weapon Flame Spit/Tongues of Fire','Bow-only skill pool'],notes='Loading status intentionally unclaimed after rebuilding; tools/check_loaded.py can read current process state.')
(root/'dist/runtime-validation.json').write_text(json.dumps(runtime,indent=2),encoding='utf8')
hexes=json.loads((root/'dist/validation.json').read_text(encoding='utf8'))['hexes']
icons=dict(version=version,hexes=[dict(id=h['Id'],name=h['Zh'],large=h['LargeIcon'],small=h['SmallIcon']) for h in hexes],source='data/reference/ui/icon-ids.json',allIdsPresentInOriginalAtlases=True,permanentSpecialEffectIcons=True,readyHudIcons={'ultimate':20297,'escape':20222},cooldownHudIconsHidden=True,gameplayVerified=False)
(root/'dist/icon-validation.json').write_text(json.dumps(icons,ensure_ascii=False,indent=2),encoding='utf8')
integration=dict(profile='NRHex.me3',excludedMods=['PowerOfBalance'],nativeFiles={str(p.relative_to(root/'dist')).replace('\\','/'):hashfile(p) for folder in ['mod/natives','testmods'] for p in (root/'dist'/folder).rglob('*') if p.is_file() and p.suffix in ['.dll','.ini','.csv']},gameplayVerified=False,loadingVerified=False)
(root/'dist/integration-validation.json').write_text(json.dumps(integration,indent=2),encoding='utf8')
print('PASS: current build/icon/config records summarized; no historical loading/gameplay claims copied.')

